package com.jmadsen.dashhop;
import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
/** Offline clock/date browser. Day/week/month are dates, not connected event data. */
final class CalendarPanel extends LinearLayout {
 final ShortcutRepository repo;final String key;Calendar cursor=Calendar.getInstance();String mode="clock",lastClockFormat="";Runnable onDaySelected;void refreshClockPreference(){if(!lastClockFormat.equals(repo.str("clock","system")))render();}boolean listening;
 CalendarPanel(Context c,ShortcutRepository r,String key){super(c);repo=r;this.key=key;setOrientation(VERTICAL);render();}
 int dp(int n){return DockController.px(getContext(),n);}
 TextView text(String s,int size){TextView t=new TextView(getContext());t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setGravity(Gravity.CENTER);return t;}
 TextView action(String title,Runnable r){TextView t=text(title,16);t.setMinHeight(dp(48));t.setOnClickListener(v->r.run());return t;}
 void format(TextClock clock,boolean date){String f=repo.str("clock","system");clock.setFormat12Hour(date?"EEEE, MMMM d, yyyy":"24".equals(f)?"HH:mm":"h:mm a");clock.setFormat24Hour(date?"EEEE, MMMM d, yyyy":"12".equals(f)?"h:mm a":"HH:mm");}
 void change(int delta){cursor.add(mode.equals("month")?Calendar.MONTH:mode.equals("week")?Calendar.WEEK_OF_YEAR:Calendar.DAY_OF_MONTH,delta);render();}
 void render(){lastClockFormat=repo.str("clock","system");removeAllViews();if(mode.equals("clock")){LinearLayout compact=new LinearLayout(getContext());compact.setOrientation(VERTICAL);compact.setGravity(Gravity.CENTER);compact.setPadding(dp(12),dp(8),dp(12),dp(8));TextClock time=new TextClock(getContext());format(time,false);time.setTextColor(0xff75e1db);time.setGravity(Gravity.CENTER);time.setAutoSizeTextTypeUniformWithConfiguration(28,84,2,android.util.TypedValue.COMPLEX_UNIT_SP);compact.addView(time,new LinearLayout.LayoutParams(-1,0,2));TextClock date=new TextClock(getContext());format(date,true);date.setTextColor(Color.WHITE);date.setGravity(Gravity.CENTER);date.setTextSize(16);compact.addView(date,new LinearLayout.LayoutParams(-1,0,1));compact.setContentDescription("Clock and date. Tap to open calendar in this panel");compact.setOnClickListener(v->{mode="month";render();});time.setOnClickListener(v->compact.performClick());date.setOnClickListener(v->compact.performClick());addView(compact,new LinearLayout.LayoutParams(-1,-1));return;}
 LinearLayout top=new LinearLayout(getContext());TextView close=action("×",()->{mode="clock";render();});close.setContentDescription("Close calendar and return to clock");top.addView(close,new LinearLayout.LayoutParams(dp(48),dp(48)));for(String view:new String[]{"month","week","day"}){TextView tab=action(view.substring(0,1).toUpperCase()+view.substring(1),()->{mode=view;render();});tab.setTextColor(mode.equals(view)?0xff75e1db:Color.WHITE);top.addView(tab,new LinearLayout.LayoutParams(0,dp(48),1));}addView(top);
 LinearLayout nav=new LinearLayout(getContext());nav.addView(action("‹",()->change(-1)),new LinearLayout.LayoutParams(dp(48),dp(48)));TextView heading=text(new SimpleDateFormat(mode.equals("month")?"MMMM yyyy":"MMM d, yyyy",Locale.getDefault()).format(cursor.getTime()),15);nav.addView(heading,new LinearLayout.LayoutParams(0,dp(48),1));nav.addView(action("Today",()->{cursor=Calendar.getInstance();render();}),new LinearLayout.LayoutParams(dp(64),dp(48)));nav.addView(action("›",()->change(1)),new LinearLayout.LayoutParams(dp(48),dp(48)));addView(nav);
 ScrollView scroll=new ScrollView(getContext());LinearLayout body=new LinearLayout(getContext());body.setOrientation(1);scroll.addView(body);addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
 if(mode.equals("month")){Calendar first=(Calendar)cursor.clone();first.set(Calendar.DAY_OF_MONTH,1);int weekStart=first.getFirstDayOfWeek(),offset=(first.get(Calendar.DAY_OF_WEEK)-weekStart+7)%7;Calendar start=(Calendar)first.clone();start.add(Calendar.DAY_OF_MONTH,-offset);HorizontalScrollView horizontal=new HorizontalScrollView(getContext());LinearLayout grid=new LinearLayout(getContext());grid.setOrientation(1);grid.setMinimumWidth(dp(336));String[] weekdays=DateFormatSymbols.getInstance().getShortWeekdays();LinearLayout labels=new LinearLayout(getContext());for(int i=0;i<7;i++)labels.addView(text(weekdays[(weekStart-1+i)%7+1],12),new LinearLayout.LayoutParams(0,dp(32),1));grid.addView(labels);for(int row=0;row<6;row++){LinearLayout line=new LinearLayout(getContext());for(int col=0;col<7;col++){Calendar day=(Calendar)start.clone();start.add(Calendar.DAY_OF_MONTH,1);TextView cell=action(Integer.toString(day.get(Calendar.DAY_OF_MONTH)),()->{cursor=day;mode="day";render();if(onDaySelected!=null)onDaySelected.run();});if(day.get(Calendar.MONTH)!=cursor.get(Calendar.MONTH))cell.setTextColor(0xff778c9a);if(same(day,Calendar.getInstance()))cell.setBackgroundColor(0xff285965);cell.setContentDescription(DateFormat.getDateInstance(DateFormat.FULL).format(day.getTime()));line.addView(cell,new LinearLayout.LayoutParams(0,dp(48),1));}grid.addView(line);}horizontal.setFillViewport(true);horizontal.addView(grid,new FrameLayout.LayoutParams(-1,-2));body.addView(horizontal);}
 else if(mode.equals("week")){Calendar start=(Calendar)cursor.clone();start.add(Calendar.DAY_OF_MONTH,-((start.get(Calendar.DAY_OF_WEEK)-start.getFirstDayOfWeek()+7)%7));for(int i=0;i<7;i++){Calendar day=(Calendar)start.clone();start.add(Calendar.DAY_OF_MONTH,1);body.addView(action(new SimpleDateFormat("EEEE, MMM d",Locale.getDefault()).format(day.getTime()),()->{cursor=day;mode="day";render();if(onDaySelected!=null)onDaySelected.run();}));}}
 else {TextView day=text(DateFormat.getDateInstance(DateFormat.FULL).format(cursor.getTime()),23);day.setPadding(dp(8),dp(16),dp(8),dp(16));body.addView(day);body.addView(onDaySelected==null?text("No connected event calendar",15):action("Show events for this date",onDaySelected));}
 }
 boolean same(Calendar a,Calendar b){return a.get(Calendar.YEAR)==b.get(Calendar.YEAR)&&a.get(Calendar.DAY_OF_YEAR)==b.get(Calendar.DAY_OF_YEAR);}
 final BroadcastReceiver changes=new BroadcastReceiver(){public void onReceive(Context c,Intent i){render();}};
 protected void onAttachedToWindow(){super.onAttachedToWindow();IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_DATE_CHANGED);f.addAction(Intent.ACTION_TIME_CHANGED);f.addAction(Intent.ACTION_TIMEZONE_CHANGED);getContext().registerReceiver(changes,f);listening=true;}
 protected void onDetachedFromWindow(){if(listening){getContext().unregisterReceiver(changes);listening=false;}super.onDetachedFromWindow();}
}
